SELECT 'STALL' AS kind, MIN(observed_at) AS t_first, MAX(created_at) AS t_last, COUNT(*) AS n, MAX(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at)) / 1000 AS max_lag_ms, NULL AS info FROM crypto_ai.market_price_event WHERE observed_at BETWEEN '2026-10-11 22:17:30' AND '2026-10-11 22:19:00' AND TIMESTAMPDIFF(MICROSECOND, observed_at, created_at) > 500000
UNION ALL SELECT 'STALL', MIN(observed_at), MAX(created_at), COUNT(*), MAX(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at)) / 1000, NULL FROM crypto_ai.market_price_event WHERE observed_at BETWEEN '2026-10-11 22:31:30' AND '2026-10-11 22:33:00' AND TIMESTAMPDIFF(MICROSECOND, observed_at, created_at) > 500000
UNION ALL SELECT 'WALLET', executed_at, executed_at, id, NULL, CONCAT(symbol, ' ', side, ' ', execution_reason) FROM crypto_ai.wallet_trade WHERE executed_at BETWEEN '2026-10-11 22:17:00' AND '2026-10-11 22:19:30' OR executed_at BETWEEN '2026-10-11 22:31:00' AND '2026-10-11 22:33:30'
ORDER BY t_first LIMIT 40;